def unique_jobs(rows):
    seen = set()
    out = []
    for r in rows:
        sid = r.get('source_id')
        if not sid:
            key = ('missing', r.get('source'))
        else:
            key = (r.get('source'), sid)
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out
